#if UNITY_EDITOR
using UnityEngine;using UnityEditor;using System.Collections;using System.IO;using System.Linq;
namespace Abyss.Story {
public class Revision13Verification:MonoBehaviour {
 System.Collections.Generic.List<string> results=new();int errors;void OnEnable()=>Application.logMessageReceived+=Log;void Log(string m,string s,LogType t){if(t==LogType.Error||t==LogType.Exception){errors++;File.AppendAllText("Tools/Revision13/errors.txt",m+"\n"+s);}}void OnDisable()=>Application.logMessageReceived-=Log;
 void Check(bool ok,string label){results.Add((ok?"PASS ":"FAIL ")+label);File.WriteAllLines("Tools/Revision13/results.txt",results);}
 IEnumerator Start(){yield return new WaitForSeconds(1);var story=FindFirstObjectByType<UnderwaterDayStory>();story.ui.Clear();story.thirdChapter.BeginThirdChapter();yield return new WaitForSeconds(2);story.ui.Clear();var brine=story.GetComponent<BrineDischarge>();var body=story.player.GetComponent<Rigidbody2D>();
 Check(brine.vesselTransform!=null,"Discharge follows actual decorative vessel transform");Check(brine.Active&&brine.frames.All(s=>s.bounds.size==brine.frames[0].bounds.size),"Brine active with identical canvas and anchored pivots");Check(brine.frames.All(s=>s.pivot==brine.frames[0].pivot),"Animation outlet pivot fixed");
 body.position=(Vector2)brine.outlet.position+new Vector2(0,-1);yield return new WaitForSeconds(.2f);int health=story.thirdChapter.Health;Check(health==2,"Discharge entry applies one normal damage unit");yield return new WaitForSeconds(.4f);Check(story.thirdChapter.Health==health,"No duplicate contact ticks before interval");body.position+=Vector2.right*3;yield return new WaitForSeconds(.5f);Check(story.thirdChapter.Health==health,"Exiting stops damage");body.position=(Vector2)brine.outlet.position+Vector2.down;yield return new WaitForSeconds(.3f);Check(story.thirdChapter.Health==1,"Re-entry respects cooldown and next interval");
 brine.dischargeEnabled=false;yield return new WaitForSeconds(1.1f);Check(!brine.Active&&story.thirdChapter.Health==1,"Disabling discharge disables visual and damage");
 Check(story.ui.GetComponentsInChildren<UnityEngine.UI.Image>().Count(i=>i.name.StartsWith("Health heart"))==3,"Three persistent heart images replace numeric health");
 var env=story.GetComponent<WarEnvironment>();Check(env.GetComponentsInChildren<SpriteRenderer>(true).Count(r=>r.name=="Floating fish skeleton")==5,"Two extra surface skeletons without extra interactions");Check(env.GetComponentsInChildren<SpriteRenderer>(true).Count(r=>r.name=="Discharge skeleton")==10,"Ten bounded discharge skeletons");Check(env.GetComponentsInChildren<SpriteRenderer>(true).Count(r=>r.name=="Discharge area waste")==8,"Local waste deposit separate from brine");
 var audio=story.GetComponent<UnderwaterSceneAudio>();Check(audio.ambience&&audio.bubble&&audio.ambienceVolume==.3f&&audio.bubbleVolume==.11f,"2D recorded ambience and bubble gain updated");Check(FindObjectsByType<AudioListener>(FindObjectsSortMode.None).Length==1,"Single AudioListener");Check(story.thirdChapter.checkpoints.All(p=>story.thirdChapter.IsSafe(p)),"Coverage changes preserve checkpoint safety");
 File.WriteAllText("Tools/Revision13/audio-diagnostics.txt","Listener volume="+AudioListener.volume+"; sources="+audio.GetComponentsInChildren<AudioSource>().Length+"; 2D="+audio.GetComponentsInChildren<AudioSource>().All(s=>s.spatialBlend==0)+"; muted="+audio.GetComponentsInChildren<AudioSource>().Count(s=>s.mute)+"; ambience gain="+audio.ambienceVolume+"; bubbles="+audio.bubbleVolume);brine.dischargeEnabled=true;
 body.position=new Vector2(-126,-21);brine.dischargeEnabled=false;var floor=Physics2D.RaycastAll(new Vector2(-50,0),Vector2.down,60).First(h=>h.collider&&!h.collider.isTrigger&&!h.collider.attachedRigidbody);var can=new GameObject("Test harmless can");can.AddComponent<SpriteRenderer>().sprite=env.waste[2];can.transform.position=new Vector2(-50,floor.point.y+.5f);var debris=can.AddComponent<WarDebris>();debris.heavy=true;debris.surface=story.player.surfaceY;yield return new WaitForSeconds(.6f);Check(Mathf.Abs(can.transform.position.y-floor.point.y-.12f)<.1f&&!can.GetComponent<Collider2D>(),"Can settles on first solid ground without blocking player");
 story.ui.Show(new[]{new UnderwaterStoryUI.Line(false,"Test")},true);brine.dischargeEnabled=true;body.position=(Vector2)brine.outlet.position+Vector2.down;int prior=story.thirdChapter.Health;yield return new WaitForSeconds(1.1f);Check(story.thirdChapter.Health==prior,"Blocking dialogue rejects discharge damage");brine.dischargeEnabled=false;story.ui.Clear();body.position=new Vector2(-126,-21);yield return new WaitForSeconds(1.1f);story.thirdChapter.TakeHit();yield return new WaitForSeconds(1.2f);Check(story.thirdChapter.Health==3&&story.ui.GetComponentsInChildren<UnityEngine.UI.Image>().Where(i=>i.name.StartsWith("Health heart")).All(i=>i.sprite==story.ui.fullHeart),"Respawn restores three full hearts");
 brine.dischargeEnabled=true;
 body.position=new Vector2(-45,11);Camera.main.transform.position=new Vector3(-45,9,-10);yield return null;Capture(story);Check(errors==0,"No new runtime errors");EditorApplication.isPlaying=false;}
 void Capture(UnderwaterDayStory story){var cam=Camera.main;cam.transform.position=new Vector3(-49,9,-10);var rt=RenderTexture.GetTemporary(1280,720,24);var old=cam.targetTexture;var active=RenderTexture.active;cam.targetTexture=rt;var canvas=story.ui.GetComponentInChildren<Canvas>();canvas.scaleFactor=720f/1080;foreach(var t in canvas.GetComponentsInChildren<UnityEngine.UI.Text>())t.SetAllDirty();Canvas.ForceUpdateCanvases();cam.Render();RenderTexture.active=rt;var image=new Texture2D(1280,720,TextureFormat.RGB24,false);image.ReadPixels(new Rect(0,0,1280,720),0,0);image.Apply();File.WriteAllBytes("Tools/Revision13/discharge.png",image.EncodeToPNG());Destroy(image);cam.targetTexture=old;RenderTexture.active=active;RenderTexture.ReleaseTemporary(rt);}
}}
#endif
